CASE = {'case_id': '12_prepare_midsurface_001_plate_t2',
 'category': '12_repair_prepare',
 'commands': ['Midsurface.Convert(bodies, thickness)',
              'MidsurfaceOffsetFaces.Create',
              'MidsurfaceAspectExtensions.SetThickness'],
 'expect': {},
 'feature': 'rp_midsurface',
 'inventory_expect': None,
 'notes': 'fix R2: Midsurface object with explicit face pair (top/bottom) first, then by thickness range, '
          'then Convert; each form checked for a created sheet',
 'out_dir': 'D:\\training\\caedecoder\\scdm_cases\\12_repair_prepare',
 'params': {'base': 'plate 100x50x2'},
 'priority': 'P1',
 'title': 'Midsurface: 001_plate_t2'}


def build(ctx):
    def chk_mid():
        if not any(is_sheet(x) for x in all_bodies()):
            raise Exception("no midsurface sheet created")
    def mk_mid():
        try:
            return Midsurface(MidsurfaceOptions())
        except Exception:
            return Midsurface()
    def mid_pairs(pairs):
        m = mk_mid()
        for f1, f2 in pairs:
            m.AddMatchingFacePairs(f1, f2)
        m.Execute()
        chk_mid()
    def mid_range(s, lo, hi):
        m = mk_mid()
        m.AddFacePairsByRange(s, MM(lo), MM(hi))
        m.Execute()
        chk_mid()
    def mid_conv(s, t):
        Midsurface.Convert(s, MM(t))
        chk_mid()

    b = block((0, 0, 0), (100, 50, 2), "Plate_T2")
    first_ok(ctx, "midsurface", [lambda: mid_pairs([(top_face(b), bottom_face(b))]), lambda: mid_range(sel(b), 1.5, 2.5),
                                 lambda: mid_conv(sel(b), 2)])
    ctx.data["bodies_after"] = [[unicode(x.Name), is_sheet(x)] for x in all_bodies()]
    sh = [x for x in all_bodies() if is_sheet(x)]
    intent("has_sheet", bool(sh), True)
    intent("sheet_z_mm", round(bbox(sh[0])[0][2], 3), 1.0, 0.01)

